// src/pages/Products.jsx

import React, { useState } from 'react';
import { categories } from '../api/categories';

function Products() {
  const [query, setQuery] = useState('');
  const [categoryQuery, setCategoryQuery] = useState('');

  return (
    <div className="container">
      <h2>Browse Books</h2>

      <div className="filters">
        <input
          type="text"
          placeholder="Search by title or author"
          value={query}
          onChange={(e) => {
            setCategoryQuery('');
            setQuery(e.target.value);
          }}
        />

        <select
          value={categoryQuery}
          onChange={(e) => {
            setQuery('');
            setCategoryQuery(e.target.value);
          }}
        >
          <option value="">Select Category</option>
          {categories.map((cat) => (
            <option key={cat.query} value={cat.query}>
              {cat.name}
            </option>
          ))}
        </select>
      </div>

      <div className="book-grid">
        <div className="book-card">
          <img
            className="book-cover"
            src="https://via.placeholder.com/160x240.png?text=Book+Cover"
            alt="Dummy Book"
          />
          <h3 className="book-title">Dummy Book Title</h3>
          <p className="book-author">Author Name</p>
          <p className="book-year">2025</p>
          <div className="book-actions">
            <button className="book-btn">Add to Cart</button>
            <button className="book-btn">Add to Wishlist</button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Products;
